import java.sql.Connection; import java.sql.DriverManager; import java.sql.ResultSet; import java.sql.Statement; public class TestDB { public static void main(String[] args) { try { Class.forName("org.postgresql.Driver"); Connection conn = DriverManager.getConnection("jdbc:postgresql://localhost:5432/supplychain", "postgres", "1234"); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery("SELECT username, password_hash, role, status FROM users"); while(rs.next()) { System.out.println("User: " + rs.getString(1) + " | Hash: " + rs.getString(2) + " | Role: " + rs.getString(3) + " | Status: " + rs.getString(4)); } } catch(Exception e) { e.printStackTrace(); } } }
